INSERT INTO ingles_bloques (slug, numero, titulo, nivel, resumen, examen) VALUES
    ('primer-contacto', 1, 'Primer contacto con el inglés', 'A1', 'Cómo suena el inglés, el alfabeto, los pronombres y las primeras frases para saludar, presentarte y sobrevivir en clase.', 'examen-primer-contacto'),
    ('construir-oraciones', 2, 'Construir oraciones', 'A1', 'El verbo to be completo (afirmar, negar, preguntar y responder), contracciones, artículos, plurales y demostrativos.', 'examen-construir-oraciones'),
    ('describir-el-mundo', 3, 'Describir el mundo', 'A1', 'Adjetivos, posesivos, there is / there are y preposiciones de lugar para describir personas, objetos, casas y ciudades.', 'examen-describir-el-mundo'),
    ('comunicacion-cotidiana', 4, 'Comunicación cotidiana', 'A1', 'Números, precios, fechas, horas, países, nacionalidades, familia, profesiones y las preguntas que se hacen todos los días.', 'examen-comunicacion-cotidiana'),
    ('rutinas-y-habitos', 5, 'Rutinas y hábitos', 'A1', 'El presente simple: afirmación, tercera persona, do / does, negaciones, preguntas y adverbios de frecuencia.', 'examen-rutinas-y-habitos'),
    ('acciones-actuales', 6, 'Acciones y situaciones actuales', 'A1-A2', 'El presente continuo, la ortografía de -ing y la diferencia entre lo que haces siempre y lo que estás haciendo ahora.', 'examen-acciones-actuales'),
    ('posesion-y-cantidades', 7, 'Expresar posesión y cantidades', 'A1-A2', 'Have y have got, sustantivos contables e incontables, some / any, much / many y cómo comprar y pedir comida.', 'examen-posesion-y-cantidades'),
    ('habilidades-y-posibilidades', 8, 'Habilidades y posibilidades', 'A1-A2', 'Can y could para hablar de habilidades, pedir permiso, hacer peticiones, sugerir y expresar posibilidad.', 'examen-habilidades-y-posibilidades'),
    ('hablar-del-pasado', 9, 'Hablar del pasado', 'A2', 'Was / were, el pasado simple con verbos regulares e irregulares, expresiones temporales, preguntas, negaciones y narraciones.', 'examen-hablar-del-pasado'),
    ('integracion', 10, 'Integración del inglés básico', 'A2', 'Todos los tiempos juntos: preguntar en cualquier tiempo, narrar experiencias, escribir correos y mantener conversaciones completas.', 'examen-integral'),
    ('ampliacion', 11, 'Ampliación: más herramientas para comunicarte', 'A2', 'Pronombres de objeto, instrucciones con el imperativo, comparar personas y cosas, y hablar del futuro con going to y will.', 'examen-ampliacion')
INSERT INTO ingles_unidades (bloque_id, slug, numero, titulo, nivel, resumen, publicada, lecciones, ejercicios, minutos) VALUES
    ((SELECT id FROM ingles_bloques WHERE slug = 'primer-contacto'), 'sonidos-y-alfabeto', 1, 'Sonidos y alfabeto', 'A1', 'Por qué el inglés no se lee como se escribe, cómo se nombran las letras y qué sonidos no existen en español.', 1, 3, 38, 110),
    ((SELECT id FROM ingles_bloques WHERE slug = 'primer-contacto'), 'saludos-y-presentaciones', 2, 'Saludos y presentaciones', 'A1', 'Saludar, despedirte, los pronombres personales, presentarte y la estructura básica de una oración.', 1, 4, 55, 135),
    ((SELECT id FROM ingles_bloques WHERE slug = 'primer-contacto'), 'palabras-para-empezar', 3, 'Palabras para empezar', 'A1', 'Frases de clase y de cortesía, objetos cotidianos y colores para empezar a comunicarte desde el primer día.', 1, 3, 39, 95),
    ((SELECT id FROM ingles_bloques WHERE slug = 'construir-oraciones'), 'verbo-to-be', 4, 'El verbo to be', 'A1', 'Am, is y are: el verbo que significa ser y estar, sus contracciones y sus usos, incluidos los que en español se dicen con tener.', 1, 3, 40, 110),
    ((SELECT id FROM ingles_bloques WHERE slug = 'construir-oraciones'), 'to-be-negacion-y-preguntas', 5, 'To be: negación, preguntas y respuestas', 'A1', 'Negar con not, preguntar invirtiendo el orden, responder con respuestas cortas y hacer preguntas con what, where y how.', 1, 4, 55, 140),
    ((SELECT id FROM ingles_bloques WHERE slug = 'construir-oraciones'), 'sustantivos-y-articulos', 6, 'Sustantivos, artículos y demostrativos', 'A1', 'A / an según el sonido, the, cuándo no se pone artículo, plurales regulares e irregulares y this, that, these, those.', 1, 4, 55, 150),
    ((SELECT id FROM ingles_bloques WHERE slug = 'describir-el-mundo'), 'adjetivos-y-descripciones', 7, 'Adjetivos y descripciones', 'A1', 'Dónde va el adjetivo, por qué no tiene plural, opuestos frecuentes y cómo describir a personas y cosas.', 1, 3, 40, 110),
    ((SELECT id FROM ingles_bloques WHERE slug = 'describir-el-mundo'), 'posesivos', 8, 'Posesivos', 'A1', 'My, your, his, her…; el genitivo ''s; los pronombres mine, yours…; y la pregunta whose.', 1, 3, 36, 105),
    ((SELECT id FROM ingles_bloques WHERE slug = 'describir-el-mundo'), 'there-is-there-are', 9, 'There is / there are y lugares', 'A1', 'Decir lo que hay, negarlo y preguntarlo, las preposiciones de lugar y la descripción de casas y ciudades.', 1, 4, 48, 160),
    ((SELECT id FROM ingles_bloques WHERE slug = 'comunicacion-cotidiana'), 'numeros', 10, 'Números', 'A1', 'Del cero al millón, la trampa de thirteen / thirty, precios, teléfonos y números ordinales.', 1, 3, 37, 125),
    ((SELECT id FROM ingles_bloques WHERE slug = 'comunicacion-cotidiana'), 'fechas-y-horas', 11, 'Fechas y horas', 'A1', 'Días, meses y estaciones; cómo decir y escribir fechas; la hora; y las preposiciones in, on y at.', 1, 4, 52, 175),
    ((SELECT id FROM ingles_bloques WHERE slug = 'comunicacion-cotidiana'), 'paises-y-nacionalidades', 12, 'Países, nacionalidades e idiomas', 'A1', 'Decir de dónde eres, la diferencia entre país, nacionalidad e idioma y por qué todas llevan mayúscula.', 1, 2, 25, 80),
    ((SELECT id FROM ingles_bloques WHERE slug = 'comunicacion-cotidiana'), 'familia-profesiones-y-preguntas', 13, 'Familia, profesiones y preguntas frecuentes', 'A1', 'Los miembros de la familia, las profesiones con a / an y el mapa completo de las palabras interrogativas.', 1, 3, 40, 130),
    ((SELECT id FROM ingles_bloques WHERE slug = 'rutinas-y-habitos'), 'presente-simple', 14, 'El presente simple', 'A1', 'Para hábitos, rutinas y verdades generales. La -s de la tercera persona, su ortografía y su pronunciación.', 1, 3, 36, 125),
    ((SELECT id FROM ingles_bloques WHERE slug = 'rutinas-y-habitos'), 'presente-simple-do-does', 15, 'Do y does: negar y preguntar', 'A1', 'El auxiliar do / does, por qué desaparece la -s del verbo principal y cómo hacer preguntas con palabras interrogativas.', 1, 3, 44, 125),
    ((SELECT id FROM ingles_bloques WHERE slug = 'rutinas-y-habitos'), 'frecuencia-y-tiempo-libre', 16, 'Frecuencia y tiempo libre', 'A1', 'always, usually, never…: dónde se colocan, how often y hablar de gustos con like, love y hate.', 1, 3, 39, 120),
    ((SELECT id FROM ingles_bloques WHERE slug = 'acciones-actuales'), 'presente-continuo', 17, 'El presente continuo', 'A1', 'Para lo que está pasando ahora: am / is / are + -ing, su ortografía, su negación y sus preguntas.', 1, 3, 40, 110),
    ((SELECT id FROM ingles_bloques WHERE slug = 'acciones-actuales'), 'simple-o-continuo', 18, '¿Presente simple o continuo?', 'A2', 'Hábito frente a ahora, las expresiones de tiempo que ayudan a decidir, los verbos de estado y el continuo para planes futuros.', 1, 3, 39, 120),
    ((SELECT id FROM ingles_bloques WHERE slug = 'posesion-y-cantidades'), 'have-y-have-got', 19, 'Have y have got', 'A1', 'Dos maneras de decir tener, cómo se niegan y preguntan, y los usos de have que no significan poseer.', 1, 3, 36, 110),
    ((SELECT id FROM ingles_bloques WHERE slug = 'posesion-y-cantidades'), 'contables-e-incontables', 20, 'Contables e incontables', 'A1-A2', 'Qué sustantivos se cuentan, some y any, much, many y a lot of, y cómo preguntar cantidades.', 1, 3, 36, 120),
    ((SELECT id FROM ingles_bloques WHERE slug = 'posesion-y-cantidades'), 'compras-y-comida', 21, 'Compras y comida', 'A2', 'Pedir, preguntar precios, envases y medidas, y pedir en un restaurante o una cafetería.', 1, 3, 35, 125),
    ((SELECT id FROM ingles_bloques WHERE slug = 'habilidades-y-posibilidades'), 'can', 22, 'Can', 'A1', 'Hablar de habilidades, pedir permiso y hacer peticiones con can, y distinguir can de can''t al escuchar.', 1, 3, 38, 110),
    ((SELECT id FROM ingles_bloques WHERE slug = 'habilidades-y-posibilidades'), 'could', 23, 'Could', 'A2', 'Habilidad en el pasado, peticiones más educadas, sugerencias y posibilidades.', 1, 3, 39, 105),
    ((SELECT id FROM ingles_bloques WHERE slug = 'hablar-del-pasado'), 'was-were', 24, 'Was y were', 'A1-A2', 'El pasado de to be: afirmación, negación, preguntas, there was / there were y dónde naciste.', 1, 3, 39, 130),
    ((SELECT id FROM ingles_bloques WHERE slug = 'hablar-del-pasado'), 'pasado-simple-regular', 25, 'Pasado simple: verbos regulares', 'A2', 'Acciones terminadas en el pasado con -ed: ortografía, las tres pronunciaciones y las expresiones de tiempo.', 1, 3, 38, 135),
    ((SELECT id FROM ingles_bloques WHERE slug = 'hablar-del-pasado'), 'pasado-simple-irregular', 26, 'Pasado simple: irregulares, preguntas y negaciones', 'A2', 'Los verbos irregulares más frecuentes, did / didn''t, las preguntas con palabras interrogativas y cómo narrar una historia.', 1, 4, 50, 200),
    ((SELECT id FROM ingles_bloques WHERE slug = 'integracion'), 'todos-los-tiempos', 27, 'Todos los tiempos juntos', 'A2', 'Un mapa de los auxiliares para preguntar y negar en cualquier tiempo y elegir el tiempo correcto en contexto.', 1, 3, 44, 120),
    ((SELECT id FROM ingles_bloques WHERE slug = 'integracion'), 'comunicacion-integrada', 28, 'Comunicación integrada', 'A2', 'Describir experiencias, escribir mensajes y correos sencillos y sostener una conversación completa.', 1, 3, 44, 135),
    ((SELECT id FROM ingles_bloques WHERE slug = 'ampliacion'), 'pronombres-de-objeto-e-imperativos', 29, 'Pronombres de objeto e imperativos', 'A1-A2', 'Me, him, her, us, them; dar instrucciones y consejos con el imperativo, y pedir y dar direcciones en la ciudad.', 1, 3, 39, 120),
    ((SELECT id FROM ingles_bloques WHERE slug = 'ampliacion'), 'comparativos-y-superlativos', 30, 'Comparativos y superlativos', 'A2', 'Comparar con -er, more y than; destacar con the -est y the most; igualdad con as… as; y los irregulares good, bad, far.', 1, 3, 39, 120),
    ((SELECT id FROM ingles_bloques WHERE slug = 'ampliacion'), 'el-futuro', 31, 'El futuro: going to y will', 'A2', 'Planes e intenciones con going to, decisiones, ofrecimientos y predicciones con will, y cuándo usar cada uno junto al presente continuo.', 1, 3, 39, 125)
