INSERT INTO ingles_lecciones (unidad_id, slug, orden, titulo, resumen, minutos, ejercicios) VALUES
    ((SELECT id FROM ingles_unidades WHERE slug = 'sonidos-y-alfabeto'), 'como-suena-el-ingles', 1, 'Cómo suena el inglés', 'Letras y sonidos no coinciden: vocales cortas y largas, la schwa y cómo leer el AFI.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'sonidos-y-alfabeto'), 'el-alfabeto', 2, 'El alfabeto y cómo deletrear', 'El nombre de cada letra, las letras que se confunden y cómo deletrear en una conversación.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'sonidos-y-alfabeto'), 'sonidos-nuevos', 3, 'Sonidos que no existen en español', 'th, h aspirada, v, sh, z y consonantes finales: dónde poner la lengua y los labios.', 40, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'saludos-y-presentaciones'), 'saludar-y-despedirse', 1, 'Saludar y despedirse', 'Hello, hi, good morning, goodbye, see you: qué decir según la hora y la confianza.', 30, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'saludos-y-presentaciones'), 'pronombres-personales', 2, 'Los pronombres personales', 'I, you, he, she, it, we, they: por qué en inglés el sujeto nunca se omite.', 35, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'saludos-y-presentaciones'), 'presentarse', 3, 'Presentarte y presentar a alguien', 'My name is, I''m, this is, nice to meet you: la primera conversación completa.', 35, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'saludos-y-presentaciones'), 'orden-de-la-oracion', 4, 'El orden de la oración', 'Sujeto + verbo + complemento, y el adjetivo antes del sustantivo.', 35, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'palabras-para-empezar'), 'frases-de-clase', 1, 'Frases para sobrevivir en clase', 'Can you repeat that?, How do you say…?, What does … mean?, I don''t understand.', 30, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'palabras-para-empezar'), 'cortesia', 2, 'Please, thank you, sorry, excuse me', 'Las palabras de cortesía y sus respuestas, con sus diferencias de uso.', 30, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'palabras-para-empezar'), 'objetos-y-colores', 3, 'Objetos cotidianos y colores', 'What''s this? It''s a pen. What color is it? It''s blue.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'verbo-to-be'), 'am-is-are', 1, 'Am, is, are: ser y estar', 'Qué significa to be, cómo cambia según el sujeto y por qué une una sola palabra ser y estar.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'verbo-to-be'), 'contracciones-to-be', 2, 'Contracciones de to be', 'I''m, you''re, she''s, it''s, we''re, they''re: cómo se escriben, cuándo se usan y cómo se oyen.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'verbo-to-be'), 'usos-de-to-be', 3, 'Usos de to be', 'Edad, estados, origen, profesión, ubicación, tiempo atmosférico: donde el español usa tener, el inglés usa be.', 40, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'to-be-negacion-y-preguntas'), 'negacion-to-be', 1, 'La negación con to be', 'Sujeto + be + not, las dos formas de contraer y el caso especial de I''m not.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'to-be-negacion-y-preguntas'), 'preguntas-to-be', 2, 'Preguntas de sí o no', 'Is she…? Are you…? La inversión y la entonación ascendente.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'to-be-negacion-y-preguntas'), 'respuestas-cortas', 3, 'Respuestas cortas', 'Yes, I am / No, I''m not: por qué no se contrae en la respuesta afirmativa.', 30, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'to-be-negacion-y-preguntas'), 'preguntas-wh-con-be', 4, 'Preguntas con what, where, who, how', 'What''s your name? Where are you from? How old are you? How are you?', 40, 16),
    ((SELECT id FROM ingles_unidades WHERE slug = 'sustantivos-y-articulos'), 'a-an', 1, 'A y an', 'El artículo indeterminado depende del SONIDO, no de la letra: an hour, a university.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'sustantivos-y-articulos'), 'the-y-sin-articulo', 2, 'The y la ausencia de artículo', 'The para lo conocido y lo único; sin artículo para hablar en general.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'sustantivos-y-articulos'), 'plurales', 3, 'Plurales', '-s, -es, -ies, plurales irregulares y las tres pronunciaciones de la -s.', 40, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'sustantivos-y-articulos'), 'demostrativos', 4, 'This, that, these, those', 'Cerca o lejos, singular o plural, y cómo preguntar What''s this?', 35, 15),
    ((SELECT id FROM ingles_unidades WHERE slug = 'adjetivos-y-descripciones'), 'posicion-del-adjetivo', 1, 'La posición del adjetivo', 'a red car, two red cars: antes del sustantivo y siempre igual.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'adjetivos-y-descripciones'), 'opuestos-y-grados', 2, 'Opuestos y grados', 'big / small, cheap / expensive… y very, quite, too.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'adjetivos-y-descripciones'), 'describir-personas', 3, 'Describir personas y cosas', 'What''s she like? What does he look like? Aspecto, carácter y objetos.', 40, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'posesivos'), 'adjetivos-posesivos', 1, 'My, your, his, her, its, our, their', 'Los adjetivos posesivos y la diferencia clave con el español «su».', 35, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'posesivos'), 'genitivo-sajon', 2, 'El genitivo ''s', 'Anna''s phone, my parents'' house: cómo y dónde se pone el apóstrofo.', 35, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'posesivos'), 'pronombres-posesivos-y-whose', 3, 'Mine, yours… y whose', 'It''s mine. Whose bag is this? It''s hers.', 35, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'there-is-there-are'), 'there-is-there-are-afirmativo', 1, 'There is y there are', 'El «hay» del inglés tiene singular y plural.', 35, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'there-is-there-are'), 'there-negacion-y-preguntas', 2, 'Negación y preguntas con there', 'There isn''t / aren''t any, Is there…?, Are there any…?, How many…?', 40, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'there-is-there-are'), 'preposiciones-de-lugar', 3, 'Preposiciones de lugar', 'in, on, under, next to, between, behind, in front of, opposite.', 40, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'there-is-there-are'), 'describir-casa-y-ciudad', 4, 'Describir una casa y una ciudad', 'Juntar there is, adjetivos y preposiciones para describir un lugar real.', 45, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'numeros'), 'numeros-0-100', 1, 'Del 0 al 100', 'Las formas irregulares, los guiones y el acento que distingue 13 de 30.', 40, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'numeros'), 'numeros-grandes-y-precios', 2, 'Números grandes, precios y teléfonos', 'hundred, thousand, million, and; dólares y centavos; oh y double.', 45, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'numeros'), 'ordinales', 3, 'Números ordinales', 'first, second, third… y cómo se abrevian: 1st, 2nd, 3rd, 4th.', 40, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'fechas-y-horas'), 'dias-meses-estaciones', 1, 'Días, meses y estaciones', 'Monday, January, summer: pronunciación y mayúsculas.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'fechas-y-horas'), 'decir-fechas', 2, 'Decir y escribir fechas', 'the fifth of May, May fifth, 05/06: por qué una fecha puede significar dos días distintos.', 45, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'fechas-y-horas'), 'la-hora', 3, 'La hora', 'What time is it? o''clock, half past, quarter to y la forma digital.', 45, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'fechas-y-horas'), 'in-on-at-tiempo', 4, 'In, on, at con el tiempo', 'in May, on Monday, at 7:30 y las expresiones sin preposición.', 45, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'paises-y-nacionalidades'), 'paises-y-nacionalidades', 1, 'Países y nacionalidades', 'Las terminaciones -an, -ish, -ese, -i y las irregulares.', 40, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'paises-y-nacionalidades'), 'de-donde-eres', 2, '¿De dónde eres? Idiomas', 'Where are you from? I''m from…, I''m…, I speak…', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'familia-profesiones-y-preguntas'), 'la-familia', 1, 'La familia', 'parents, siblings, cousins… y cómo presentar a tu familia.', 45, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'familia-profesiones-y-preguntas'), 'profesiones', 2, 'Profesiones', 'I''m a teacher: el artículo que el español omite y dónde trabaja cada uno.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'familia-profesiones-y-preguntas'), 'palabras-interrogativas', 3, 'Las palabras interrogativas', 'who, what, where, when, why, how, which, whose, how many, how much.', 45, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'presente-simple'), 'que-es-el-presente-simple', 1, 'Qué es el presente simple', 'Hábitos, rutinas y verdades generales: I work, you work… y la forma base del verbo.', 35, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'presente-simple'), 'tercera-persona', 2, 'La tercera persona: he works', 'Por qué aparece la -s, sus reglas de ortografía, has, does, goes y su pronunciación.', 45, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'presente-simple'), 'rutina-diaria', 3, 'La rutina diaria', 'get up, have breakfast, go to work: verbos frecuentes y conectores de secuencia.', 45, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'presente-simple-do-does'), 'negacion-presente-simple', 1, 'La negación: don''t y doesn''t', 'El auxiliar se lleva la -s: she doesn''t work, nunca she doesn''t works.', 40, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'presente-simple-do-does'), 'preguntas-presente-simple', 2, 'Preguntas y respuestas cortas', 'Do you…? Does he…? Yes, he does / No, he doesn''t.', 40, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'presente-simple-do-does'), 'preguntas-wh-presente-simple', 3, 'Preguntas con palabras interrogativas', 'Where do you live? What time does the shop open? y la diferencia con las preguntas de be.', 45, 16),
    ((SELECT id FROM ingles_unidades WHERE slug = 'frecuencia-y-tiempo-libre'), 'adverbios-de-frecuencia', 1, 'Adverbios de frecuencia', 'always, usually, often, sometimes, rarely, never y su posición exacta.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'frecuencia-y-tiempo-libre'), 'how-often', 2, 'How often? Expresiones de frecuencia', 'once a week, twice a month, every day: al final de la frase.', 35, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'frecuencia-y-tiempo-libre'), 'gustos', 3, 'Gustos: like, love, hate', 'I like music. She loves cooking. Do you like…?', 45, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'presente-continuo'), 'que-es-el-presente-continuo', 1, 'Qué es el presente continuo', 'I''m working: acciones en progreso ahora mismo o en este periodo.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'presente-continuo'), 'ortografia-ing', 2, 'La ortografía de -ing', 'make → making, run → running, lie → lying: tres reglas y sus excepciones.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'presente-continuo'), 'negacion-y-preguntas-continuo', 3, 'Negación y preguntas', 'She isn''t sleeping. Are you listening? What are you doing?', 40, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'simple-o-continuo'), 'habito-o-ahora', 1, 'Hábito o ahora', 'I work / I''m working: la línea del tiempo y las expresiones que lo señalan.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'simple-o-continuo'), 'verbos-de-estado', 2, 'Verbos de estado', 'know, like, want, need, understand: por qué no se dice I''m knowing.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'simple-o-continuo'), 'continuo-para-planes', 3, 'El continuo para planes', 'I''m meeting Ana on Friday: agenda y planes ya organizados.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'have-y-have-got'), 'have-presente-simple', 1, 'Have: tener', 'I have, she has; I don''t have; Do you have…?', 35, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'have-y-have-got'), 'have-got', 2, 'Have got', 'I''ve got, she''s got; I haven''t got; Have you got…? y cuándo se prefiere.', 40, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'have-y-have-got'), 'expresiones-con-have', 3, 'Expresiones con have', 'have breakfast, have a shower, have a good time: acciones, no posesión.', 35, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'contables-e-incontables'), 'contable-o-incontable', 1, '¿Contable o incontable?', 'an apple / some water; information, advice, furniture y otras trampas.', 40, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'contables-e-incontables'), 'some-y-any', 2, 'Some y any', 'some en afirmaciones y ofrecimientos, any en negaciones y preguntas.', 40, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'contables-e-incontables'), 'much-many-a-lot-of', 3, 'Much, many, a lot of', 'How much…? How many…? a few, a little.', 40, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'compras-y-comida'), 'en-la-tienda', 1, 'En la tienda', 'How much is this? Can I pay by card? I''m just looking.', 40, 11),
    ((SELECT id FROM ingles_unidades WHERE slug = 'compras-y-comida'), 'envases-y-medidas', 2, 'Envases y medidas', 'a bottle of water, a slice of bread: cómo contar lo incontable.', 40, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'compras-y-comida'), 'pedir-comida', 3, 'Pedir en una cafetería o restaurante', 'I''d like…, Can I have…?, Could we have the bill, please?', 45, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'can'), 'can-habilidad', 1, 'Can para habilidades', 'I can swim. She can''t drive. Un verbo que nunca cambia.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'can'), 'can-negacion-y-preguntas', 2, 'Can: negación, preguntas y pronunciación', 'Can you…? Yes, I can. Y cómo se oye la diferencia entre can y can''t.', 40, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'can'), 'can-permiso-y-peticiones', 3, 'Permisos y peticiones', 'Can I open the window? Can you help me? Sure! / Sorry, I can''t.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'could'), 'could-pasado', 1, 'Could para el pasado', 'When I was five, I could swim. I couldn''t sleep last night.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'could'), 'could-peticiones', 2, 'Could para pedir con cortesía', 'Could you…? Could I…? y la diferencia de tono con can.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'could'), 'could-sugerencias-y-posibilidad', 3, 'Sugerencias y posibilidades', 'We could go to the beach. It could be true.', 35, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'was-were'), 'was-were-afirmativo', 1, 'Was y were', 'I was, you were: el pasado de ser y estar.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'was-were'), 'was-were-negacion-y-preguntas', 2, 'Negación y preguntas', 'It wasn''t cold. Were you at home? Yes, I was.', 45, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'was-were'), 'there-was-y-born', 3, 'There was / there were y I was born', 'Lo que había antes, y por qué «nací» se dice con was.', 45, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'pasado-simple-regular'), 'que-es-el-pasado-simple', 1, 'Qué es el pasado simple', 'Acciones terminadas: I worked yesterday. Una sola forma para todos los sujetos.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'pasado-simple-regular'), 'ortografia-y-pronunciacion-ed', 2, 'Ortografía y pronunciación de -ed', 'stopped, studied, played; /t/, /d/, /ɪd/.', 50, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'pasado-simple-regular'), 'expresiones-de-pasado', 3, 'Expresiones de pasado', 'yesterday, last week, two days ago, in 2019, when I was a child.', 45, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'pasado-simple-irregular'), 'verbos-irregulares', 1, 'Verbos irregulares frecuentes', 'go → went, have → had, see → saw… agrupados para memorizarlos mejor.', 50, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'pasado-simple-irregular'), 'did-negacion-y-preguntas', 2, 'Did: negación y preguntas', 'I didn''t go. Did you see it? El auxiliar se lleva el pasado.', 50, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'pasado-simple-irregular'), 'preguntas-wh-pasado', 3, 'Preguntas con palabras interrogativas', 'Where did you go? What did she say? Who called you?', 50, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'pasado-simple-irregular'), 'narrar', 4, 'Narrar una experiencia', 'first, then, after that, finally: contar una historia en orden.', 50, 12),
    ((SELECT id FROM ingles_unidades WHERE slug = 'todos-los-tiempos'), 'mapa-de-auxiliares', 1, 'El mapa de los auxiliares', 'Una sola regla para negar y preguntar: busca el auxiliar.', 40, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'todos-los-tiempos'), 'elegir-el-tiempo', 2, 'Elegir el tiempo correcto', 'Las señales del contexto que indican cada tiempo.', 40, 15),
    ((SELECT id FROM ingles_unidades WHERE slug = 'todos-los-tiempos'), 'preguntas-en-todos-los-tiempos', 3, 'Preguntas en todos los tiempos', 'La misma información preguntada en presente, continuo, pasado y con can.', 40, 15),
    ((SELECT id FROM ingles_unidades WHERE slug = 'comunicacion-integrada'), 'describir-experiencias', 1, 'Describir experiencias', 'Qué pasó, cómo fue y qué opinas: pasado + adjetivos + opinión.', 45, 14),
    ((SELECT id FROM ingles_unidades WHERE slug = 'comunicacion-integrada'), 'escribir-mensajes-y-correos', 2, 'Escribir mensajes y correos', 'Hi Ana, / Dear Mr Smith, … Best wishes: la estructura y el registro.', 45, 15),
    ((SELECT id FROM ingles_unidades WHERE slug = 'comunicacion-integrada'), 'mantener-una-conversacion', 3, 'Mantener una conversación', 'Reaccionar (Really? That''s great!), devolver la pregunta (And you?) y pedir aclaraciones.', 45, 15),
    ((SELECT id FROM ingles_unidades WHERE slug = 'pronombres-de-objeto-e-imperativos'), 'pronombres-de-objeto', 1, 'Me, him, her, us, them', 'El pronombre que recibe la acción: I love her, not «I love she»; y después de preposiciones: with me, for them.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'pronombres-de-objeto-e-imperativos'), 'imperativo', 2, 'El imperativo', 'Open the door. Don''t touch it. Let''s go: instrucciones, avisos, invitaciones y cómo suavizarlas con please.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'pronombres-de-objeto-e-imperativos'), 'direcciones', 3, 'Pedir y dar direcciones', 'Excuse me, where''s the station? Go straight, turn left, it''s on your right.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'comparativos-y-superlativos'), 'comparativos', 1, 'Comparativos: bigger than, more expensive than', 'Una sílaba: -er; dos o más: more; las reglas de ortografía y than.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'comparativos-y-superlativos'), 'superlativos', 2, 'Superlativos: the biggest, the most expensive', 'The + -est o the most, in / of después, y los irregulares.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'comparativos-y-superlativos'), 'as-as-y-comparar', 3, 'As… as y comparar en conversación', 'as tall as, not as cheap as, much bigger, a bit older, y cómo comparar opciones al decidir.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'el-futuro'), 'going-to', 1, 'Going to: planes y predicciones con evidencia', 'I''m going to study medicine. Look at the clouds: it''s going to rain.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'el-futuro'), 'will', 2, 'Will: decisiones, ofrecimientos y predicciones', 'I''ll help you. I think it will be sunny. I won''t tell anyone.', 40, 13),
    ((SELECT id FROM ingles_unidades WHERE slug = 'el-futuro'), 'elegir-el-futuro', 3, '¿Going to, will o presente continuo?', 'Plan, decisión en el momento, cita acordada o predicción: la señal que decide.', 45, 13)
INSERT INTO ingles_temas (slug, nombre, icono, descripcion, orden) VALUES
    ('saludos', 'Saludos y cortesía', '👋', 'Saludos, despedidas, fórmulas de cortesía (please, thank you, sorry, excuse me) y tratamientos (Mr., Ms.). Sirve para «Sonidos y alfabeto» y «Saludos y presentaciones».', 1),
    ('clase-y-objetos', 'La clase y sus objetos', '✏️', 'Útiles escolares, muebles del salón y las instrucciones que da un profesor (read, write, listen, repeat). Sirve para «Palabras para empezar» y «Sustantivos, artículos y demostrativos».', 2),
    ('colores', 'Colores', '🎨', 'Colores básicos y los adjetivos que los matizan (light, dark, bright, pale). Sirve para «Palabras para empezar» y para describir objetos y ropa.', 3),
    ('sentimientos-y-estados', 'Sentimientos y estados', '😊', 'Cómo te sientes y cómo estás: emociones, cansancio, hambre, frío… Casi todos se usan con to be, no con have. Sirve para «El verbo to be» y «To be: negación, preguntas y respuestas».', 4),
    ('hogar', 'La casa', '🏠', 'Partes de la casa, habitaciones, muebles y aparatos domésticos. Sirve para «Sustantivos, artículos y demostrativos» y «There is / there are y lugares».', 5),
    ('adjetivos-frecuentes', 'Adjetivos frecuentes', '⚖️', 'Los adjetivos más usados, casi todos en parejas de opuestos (big/small, cheap/expensive, easy/difficult). Sirve para «Adjetivos y descripciones» y para todo el curso.', 6),
    ('cuerpo-y-aspecto', 'El cuerpo y el aspecto físico', '🧍', 'Partes del cuerpo y palabras para describir a una persona (tall, thin, curly hair, glasses). Sirve para «Adjetivos y descripciones» y para hablar de salud.', 7),
    ('familia', 'La familia', '👪', 'Parientes cercanos y lejanos, pareja y estado civil. Sirve para «Posesivos», «Familia, profesiones y preguntas frecuentes» y «Have y have got».', 8),
    ('ciudad', 'La ciudad', '🏙️', 'Lugares de la ciudad, calles y preposiciones para ubicarlos (next to, across from, near). Sirve para «There is / there are y lugares» y para pedir direcciones.', 9),
    ('numeros', 'Números', '🔢', 'Números cardinales clave, decenas, centenas, ordinales básicos y half. Sirve para la unidad «Números», precios, edades y fechas.', 10),
    ('tiempo-y-calendario', 'El tiempo y el calendario', '📅', 'Partes del día, días de la semana, estaciones y palabras para ubicar algo en el tiempo (today, yesterday, ago). Sirve para «Fechas y horas» y «Was y were».', 11),
    ('paises', 'Países, nacionalidades e idiomas', '🌎', 'Países frecuentes con su nacionalidad e idioma, y las palabras para hablar de ellos. Sirve para «Países, nacionalidades e idiomas».', 12),
    ('trabajo-y-profesiones', 'Trabajo y profesiones', '💼', 'Profesiones comunes y el vocabulario de la oficina y el empleo. Sirve para «Familia, profesiones y preguntas frecuentes» y «Do y does: negar y preguntar».', 13),
    ('actividades-diarias', 'Actividades diarias', '⏰', 'Verbos y expresiones de la rutina, del despertar a la hora de dormir, con sus formas regulares e irregulares. Sirve para el presente simple, el presente continuo y el pasado regular.', 14),
    ('tiempo-libre', 'Tiempo libre', '⚽', 'Deportes, pasatiempos, música y planes para el fin de semana. Sirve para «Frecuencia y tiempo libre», «¿Presente simple o continuo?» y «Can».', 15),
    ('tecnologia', 'Tecnología', '💻', 'Aparatos, internet y las acciones que haces con ellos (download, send, turn on). Sirve para «¿Presente simple o continuo?» y «Comunicación integrada».', 16),
    ('salud', 'La salud', '🩺', 'Malestares frecuentes, medicinas y cómo hablar con un médico. Sirve para «Have y have got» y «Comunicación integrada».', 17),
    ('comida', 'La comida', '🍎', 'Comidas del día, alimentos básicos, frutas y bebidas, con atención a contables e incontables. Sirve para «Contables e incontables» y «Compras y comida».', 18),
    ('compras', 'Las compras', '🛍️', 'Tiendas, dinero, precios y lo que dices al comprar (How much…?, try on, receipt). Sirve para «Compras y comida».', 19),
    ('viajes', 'Los viajes', '🧳', 'Vacaciones, aeropuerto, equipaje y lugares turísticos, con verbos irregulares muy usados al contar un viaje. Sirve para «Could», «Pasado simple: irregulares» y «Comunicación integrada».', 20),
    ('transporte', 'El transporte', '🚌', 'Medios de transporte, la calle y los verbos para moverte (take the bus, get off, drive). Complementa «Could», los viajes y las direcciones.', 21),
    ('ropa', 'La ropa', '👕', 'Prendas, calzado y accesorios, más los verbos wear, put on y take off. Complementa «Compras y comida» y las descripciones de personas.', 22)
INSERT INTO ingles_palabras (tema_id, clave, en, es, tipo, ipa, ejemplo_en, ejemplo_es) VALUES
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.hello', 'hello', 'hola', 'interjeccion', '/həˈloʊ/', 'Hello, I''m Ana. I''m your new neighbor.', 'Hola, soy Ana. Soy tu nueva vecina.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.hi', 'hi', 'hola', 'interjeccion', '/haɪ/', 'Hi, Tom! How are you?', '¡Hola, Tom! ¿Cómo estás?'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.goodbye', 'goodbye', 'adiós', 'interjeccion', '/ɡʊdˈbaɪ/', 'Goodbye, Mrs. Lee. See you on Monday.', 'Adiós, señora Lee. Nos vemos el lunes.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.bye', 'bye', 'adiós / bye', 'interjeccion', '/baɪ/', 'Bye, Mom! I''m late for school.', '¡Adiós, mamá! Voy tarde a la escuela.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.good-morning', 'good morning', 'buenos días', 'expresion', '/ɡʊd ˈmɔrnɪŋ/', 'Good morning, everyone. Please sit down.', 'Buenos días a todos. Siéntense, por favor.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.good-afternoon', 'good afternoon', 'buenas tardes', 'expresion', '/ɡʊd ˌæftərˈnun/', 'Good afternoon. Can I help you?', 'Buenas tardes. ¿En qué le puedo ayudar?'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.good-evening', 'good evening', 'buenas tardes / buenas noches (al llegar)', 'expresion', '/ɡʊd ˈivnɪŋ/', 'Good evening, and welcome to the show.', 'Buenas noches y bienvenidos al programa.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.good-night', 'good night', 'buenas noches (al despedirse o ir a dormir)', 'expresion', '/ɡʊd ˈnaɪt/', 'Good night, Sam. Sleep well.', 'Buenas noches, Sam. Que duermas bien.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.please', 'please', 'por favor', 'adverbio', '/pliz/', 'Can I have some water, please?', '¿Me das un poco de agua, por favor?'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.thank-you', 'thank you', 'gracias', 'expresion', '/ˈθæŋk ju/', 'Thank you for the flowers, Priya!', '¡Gracias por las flores, Priya!'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.thanks', 'thanks', 'gracias', 'expresion', '/θæŋks/', 'Thanks a lot, Diego. You''re very kind.', 'Muchas gracias, Diego. Eres muy amable.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.youre-welcome', 'you''re welcome', 'de nada', 'expresion', '/jʊr ˈwɛlkəm/', '"Thanks for your help." "You''re welcome."', '—Gracias por tu ayuda. —De nada.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.sorry', 'sorry', 'perdón / lo siento', 'interjeccion', '/ˈsɑri/', 'Sorry, I don''t understand. Can you repeat that?', 'Perdón, no entiendo. ¿Puedes repetirlo?'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.excuse-me', 'excuse me', 'disculpe / con permiso', 'expresion', '/ɪkˈskjuz mi/', 'Excuse me, where is the bathroom?', 'Disculpe, ¿dónde está el baño?'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.nice-to-meet-you', 'nice to meet you', 'mucho gusto / encantado de conocerte', 'expresion', '/ˈnaɪs tə ˈmit ju/', '"This is my friend Omar." "Nice to meet you, Omar."', '—Él es mi amigo Omar. —Mucho gusto, Omar.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.how-are-you', 'how are you', '¿cómo estás? / ¿cómo está usted?', 'expresion', '/ˌhaʊ ˈɑr ju/', 'Hi, Grace! How are you today?', '¡Hola, Grace! ¿Cómo estás hoy?'),
    ((SELECT id FROM ingles_temas WHERE slug = 'saludos'), 'saludos.fine', 'fine', 'bien', 'adjetivo', '/faɪn/', 'I''m fine, thanks. And you?', 'Estoy bien, gracias. ¿Y tú?'),
