    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.money', 'money', 'dinero', 'sustantivo', '/ˈmʌni/', 'I don''t have much money right now.', 'Ahorita no tengo mucho dinero.'),
