    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.credit-card', 'credit card', 'tarjeta de crédito', 'sustantivo', '/ˈkrɛdɪt ˌkɑrd/', 'Can I pay with a credit card?', '¿Puedo pagar con tarjeta de crédito?'),
    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.change', 'change', 'cambio (dinero) / cambiar', 'sustantivo', '/tʃeɪndʒ/', 'Here is your change: two dollars and fifty cents.', 'Aquí tiene su cambio: dos dólares con cincuenta centavos.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.receipt', 'receipt', 'recibo / ticket (de compra)', 'sustantivo', '/rɪˈsit/', 'Here is your receipt. Have a nice day!', 'Aquí tiene su ticket. ¡Que tenga buen día!'),
    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.customer', 'customer', 'cliente', 'sustantivo', '/ˈkʌstəmər/', 'The store has a lot of customers on weekends.', 'La tienda tiene muchos clientes los fines de semana.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.size', 'size', 'talla / tamaño', 'sustantivo', '/saɪz/', '"What size are you?" "Medium."', '—¿Qué talla eres? —Mediana.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.sale', 'sale', 'venta / rebaja / barata', 'sustantivo', '/seɪl/', 'These jeans are on sale. They''re only twenty dollars.', 'Estos jeans están en oferta. Solo cuestan veinte dólares.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.discount', 'discount', 'descuento', 'sustantivo', '/ˈdɪskaʊnt/', 'Students get a ten percent discount.', 'Los estudiantes tienen un diez por ciento de descuento.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.try-on', 'try on', 'probarse (ropa)', 'verbo', '/ˌtraɪ ˈɑn/', 'Can I try on these shoes?', '¿Me puedo probar estos zapatos?'),
    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.cart', 'cart', 'carrito (de supermercado)', 'sustantivo', '/kɑrt/', 'The cart is full. Let''s go to the checkout.', 'El carrito está lleno. Vamos a la caja.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.shopping-bag', 'shopping bag', 'bolsa de compras / bolsa del mandado', 'sustantivo', '/ˈʃɑpɪŋ ˌbæɡ/', 'I always take my own shopping bag to the market.', 'Siempre llevo mi propia bolsa del mandado al mercado.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.dollar', 'dollar', 'dólar', 'sustantivo', '/ˈdɑlər/', 'The book costs fifteen dollars.', 'El libro cuesta quince dólares.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.cent', 'cent', 'centavo', 'sustantivo', '/sɛnt/', 'It costs ninety-nine cents.', 'Cuesta noventa y nueve centavos.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.go-shopping', 'go shopping', 'ir de compras', 'expresion', '/ˌɡoʊ ˈʃɑpɪŋ/', 'Ana and her sister go shopping every Saturday.', 'Ana y su hermana van de compras todos los sábados.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'compras'), 'compras.closed', 'closed', 'cerrado', 'adjetivo', '/kloʊzd/', 'Sorry, we''re closed. We open at ten tomorrow.', 'Lo siento, ya cerramos. Mañana abrimos a las diez.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.trip', 'trip', 'viaje', 'sustantivo', '/trɪp/', 'Our trip to Oaxaca is in December.', 'Nuestro viaje a Oaxaca es en diciembre.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.travel', 'travel', 'viajar', 'verbo', '/ˈtrævəl/', 'My parents travel a lot now.', 'Mis papás viajan mucho ahora.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.vacation', 'vacation', 'vacaciones', 'sustantivo', '/veɪˈkeɪʃən/', 'We go on vacation every summer.', 'Nos vamos de vacaciones cada verano.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.tourist', 'tourist', 'turista', 'sustantivo', '/ˈtʊrɪst/', 'Many tourists visit the pyramids every year.', 'Muchos turistas visitan las pirámides cada año.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.passport', 'passport', 'pasaporte', 'sustantivo', '/ˈpæsˌpɔrt/', 'Don''t forget your passport!', '¡No olvides tu pasaporte!'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.suitcase', 'suitcase', 'maleta', 'sustantivo', '/ˈsutˌkeɪs/', 'My suitcase is very heavy.', 'Mi maleta está muy pesada.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.luggage', 'luggage', 'equipaje', 'sustantivo', '/ˈlʌɡɪdʒ/', 'How much luggage do you have?', '¿Cuánto equipaje trae?'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.ticket', 'ticket', 'boleto', 'sustantivo', '/ˈtɪkɪt/', 'Two tickets to Guadalajara, please.', 'Dos boletos a Guadalajara, por favor.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.reservation', 'reservation', 'reservación', 'sustantivo', '/ˌrɛzərˈveɪʃən/', 'I have a reservation for two nights.', 'Tengo una reservación para dos noches.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.airport', 'airport', 'aeropuerto', 'sustantivo', '/ˈɛrˌpɔrt/', 'The airport is forty minutes from the city.', 'El aeropuerto está a cuarenta minutos de la ciudad.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.flight', 'flight', 'vuelo', 'sustantivo', '/flaɪt/', 'Our flight leaves at 6 a.m.', 'Nuestro vuelo sale a las 6 de la mañana.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.fly', 'fly', 'volar / ir en avión', 'verbo', '/flaɪ/', 'We fly to Cancún on Friday.', 'Volamos a Cancún el viernes.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.check-in', 'check in', 'registrarse / documentar (equipaje)', 'verbo', '/ˌtʃɛk ˈɪn/', 'You can check in at the hotel after three.', 'Puedes registrarte en el hotel después de las tres.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.beach', 'beach', 'playa', 'sustantivo', '/bitʃ/', 'The kids play on the beach all day.', 'Los niños juegan en la playa todo el día.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.mountain', 'mountain', 'montaña', 'sustantivo', '/ˈmaʊntən/', 'There''s snow on the mountains in winter.', 'En invierno hay nieve en las montañas.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.island', 'island', 'isla', 'sustantivo', '/ˈaɪlənd/', 'We take a boat to the island.', 'Tomamos una lancha a la isla.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.lake', 'lake', 'lago', 'sustantivo', '/leɪk/', 'There''s a beautiful lake near the town.', 'Hay un lago precioso cerca del pueblo.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.sightseeing', 'sightseeing', 'turismo / visitar lugares de interés', 'sustantivo', '/ˈsaɪtˌsiɪŋ/', 'We go sightseeing in the morning and rest in the afternoon.', 'En la mañana salimos a conocer la ciudad y en la tarde descansamos.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.souvenir', 'souvenir', 'recuerdo (de un viaje)', 'sustantivo', '/ˌsuvəˈnɪr/', 'I always buy a small souvenir for my mom.', 'Siempre le compro un pequeño recuerdo a mi mamá.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.abroad', 'abroad', 'al extranjero / en el extranjero', 'adverbio', '/əˈbrɔd/', 'Omar wants to study abroad.', 'Omar quiere estudiar en el extranjero.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.visit', 'visit', 'visitar / visita', 'verbo', '/ˈvɪzɪt/', 'We visit a different museum every day.', 'Visitamos un museo diferente cada día.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.see', 'see', 'ver / conocer (un lugar)', 'verbo', '/si/', 'We saw the pyramids and a lot of old churches.', 'Vimos las pirámides y muchas iglesias antiguas.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.take-a-photo', 'take a photo', 'tomar una foto', 'expresion', '/ˌteɪk ə ˈfoʊtoʊ/', 'Excuse me, can you take a photo of us?', 'Disculpe, ¿nos puede tomar una foto?'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.pack', 'pack', 'empacar / hacer la maleta', 'verbo', '/pæk/', 'I always pack the night before a trip.', 'Siempre hago la maleta la noche antes de un viaje.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.bring', 'bring', 'traer / llevar (consigo)', 'verbo', '/brɪŋ/', 'Bring a jacket. It''s cold in the mountains.', 'Trae una chamarra. En la montaña hace frío.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.lose', 'lose', 'perder', 'verbo', '/luz/', 'Ben always loses his keys.', 'Ben siempre pierde sus llaves.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.get-lost', 'get lost', 'perderse', 'expresion', '/ˌɡɛt ˈlɔst/', 'I always get lost in big cities.', 'Siempre me pierdo en las ciudades grandes.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'viajes'), 'viajes.find', 'find', 'encontrar', 'verbo', '/faɪnd/', 'Can you help me? I can''t find my hotel.', '¿Me puede ayudar? No encuentro mi hotel.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.car', 'car', 'carro / coche / auto', 'sustantivo', '/kɑr/', 'Tom goes to work by car.', 'Tom va al trabajo en carro.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.bus', 'bus', 'camión / autobús', 'sustantivo', '/bʌs/', 'I take the bus to school.', 'Tomo el camión para ir a la escuela.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.train', 'train', 'tren', 'sustantivo', '/treɪn/', 'The train to the airport is fast and cheap.', 'El tren al aeropuerto es rápido y barato.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.airplane', 'airplane', 'avión', 'sustantivo', '/ˈɛrˌpleɪn/', 'It''s my first time on an airplane.', 'Es mi primera vez en un avión.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.bicycle', 'bicycle', 'bicicleta', 'sustantivo', '/ˈbaɪsɪkəl/', 'Mei goes to the university by bicycle.', 'Mei va a la universidad en bicicleta.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.motorcycle', 'motorcycle', 'motocicleta / moto', 'sustantivo', '/ˈmoʊtərˌsaɪkəl/', 'My cousin has a red motorcycle.', 'Mi primo tiene una moto roja.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.taxi', 'taxi', 'taxi', 'sustantivo', '/ˈtæksi/', 'Let''s take a taxi. It''s late.', 'Tomemos un taxi. Ya es tarde.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.subway', 'subway', 'metro', 'sustantivo', '/ˈsʌbˌweɪ/', 'I go downtown by subway. It''s fast and cheap.', 'Voy al centro en metro. Es rápido y barato.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.ship', 'ship', 'barco (grande) / buque', 'sustantivo', '/ʃɪp/', 'A big ship arrives at the port every morning.', 'Cada mañana llega un barco grande al puerto.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.boat', 'boat', 'lancha / bote / barco', 'sustantivo', '/boʊt/', 'We can go to the island by boat.', 'Podemos ir a la isla en lancha.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.truck', 'truck', 'camión (de carga) / camioneta', 'sustantivo', '/trʌk/', 'A big truck is blocking the street.', 'Un camión grande está bloqueando la calle.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.helicopter', 'helicopter', 'helicóptero', 'sustantivo', '/ˈhɛlɪˌkɑptər/', 'There''s a helicopter over the hospital.', 'Hay un helicóptero sobre el hospital.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.drive', 'drive', 'manejar / conducir / llevar en carro', 'verbo', '/draɪv/', 'Can you drive? I''m very tired.', '¿Puedes manejar tú? Estoy muy cansado.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.ride', 'ride', 'andar en / montar / paseo', 'verbo', '/raɪd/', 'The kids ride their bikes in the park.', 'Los niños andan en bici en el parque.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.take', 'take', 'tomar (un transporte) / llevar / tardar', 'verbo', '/teɪk/', 'I take the bus to work. It takes twenty minutes.', 'Tomo el camión para ir al trabajo. Tardo veinte minutos.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.get-on', 'get on', 'subirse (a un camión, tren, avión, bici)', 'verbo', '/ˌɡɛt ˈɑn/', 'Get on the bus at the next stop.', 'Súbete al camión en la siguiente parada.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.get-off', 'get off', 'bajarse (de un camión, tren, avión, bici)', 'verbo', '/ˌɡɛt ˈɔf/', 'Get off the train at the third station.', 'Bájate del tren en la tercera estación.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.miss', 'miss', 'perder (un transporte) / extrañar', 'verbo', '/mɪs/', 'Sam misses the bus every Monday.', 'Sam pierde el camión todos los lunes.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.on-foot', 'on foot', 'a pie / caminando', 'expresion', '/ˌɑn ˈfʊt/', 'The park is close. We can go on foot.', 'El parque está cerca. Podemos ir a pie.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.road', 'road', 'camino / carretera / calle', 'sustantivo', '/roʊd/', 'This road goes to the beach.', 'Este camino va a la playa.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.highway', 'highway', 'carretera / autopista', 'sustantivo', '/ˈhaɪˌweɪ/', 'There''s a lot of traffic on the highway today.', 'Hoy hay mucho tráfico en la carretera.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.traffic', 'traffic', 'tráfico', 'sustantivo', '/ˈtræfɪk/', 'Sorry I''m late. There''s a lot of traffic.', 'Perdón por llegar tarde. Hay mucho tráfico.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.parking-lot', 'parking lot', 'estacionamiento', 'sustantivo', '/ˈpɑrkɪŋ ˌlɑt/', 'The parking lot behind the mall is free.', 'El estacionamiento detrás de la plaza es gratis.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.passenger', 'passenger', 'pasajero', 'sustantivo', '/ˈpæsɪndʒər/', 'The bus has forty passengers.', 'El camión lleva cuarenta pasajeros.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.seat-belt', 'seat belt', 'cinturón de seguridad', 'sustantivo', '/ˈsit ˌbɛlt/', 'Please put on your seat belt.', 'Por favor, ponte el cinturón de seguridad.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.gas', 'gas', 'gasolina / gas', 'sustantivo', '/ɡæs/', 'Gas is very expensive this month.', 'La gasolina está muy cara este mes.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.wait', 'wait', 'esperar (que algo pase o llegue)', 'verbo', '/weɪt/', 'We wait for the bus for twenty minutes every morning.', 'Esperamos el camión veinte minutos cada mañana.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'transporte'), 'transporte.late', 'late', 'tarde / retrasado', 'adjetivo', '/leɪt/', 'The train is late again.', 'El tren viene retrasado otra vez.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.clothes', 'clothes', 'ropa', 'sustantivo', '/kloʊz/', 'I need new clothes for my new job.', 'Necesito ropa nueva para mi nuevo trabajo.'),
