    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.shirt', 'shirt', 'camisa', 'sustantivo', '/ʃɜrt/', 'He''s wearing a white shirt and a blue tie.', 'Trae una camisa blanca y una corbata azul.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.pants', 'pants', 'pantalones / pantalón', 'sustantivo', '/pænts/', 'These pants are too long for me.', 'Estos pantalones me quedan demasiado largos.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.jeans', 'jeans', 'jeans / pantalón de mezclilla', 'sustantivo', '/dʒinz/', 'My favorite jeans are old but comfortable.', 'Mis jeans favoritos están viejos pero son cómodos.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.shorts', 'shorts', 'shorts / pantalones cortos', 'sustantivo', '/ʃɔrts/', 'It''s hot. Wear shorts today.', 'Hace calor. Ponte shorts hoy.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.dress', 'dress', 'vestido', 'sustantivo', '/drɛs/', 'Lucía has a beautiful red dress for the party.', 'Lucía tiene un vestido rojo precioso para la fiesta.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.skirt', 'skirt', 'falda', 'sustantivo', '/skɜrt/', 'The school uniform is a gray skirt and a white shirt.', 'El uniforme de la escuela es falda gris y camisa blanca.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.sweater', 'sweater', 'suéter', 'sustantivo', '/ˈswɛtər/', 'Take a sweater. It''s cold tonight.', 'Llévate un suéter. Hace frío esta noche.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.jacket', 'jacket', 'chamarra / saco', 'sustantivo', '/ˈdʒækɪt/', 'Omar has a black leather jacket.', 'Omar tiene una chamarra de piel negra.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.coat', 'coat', 'abrigo', 'sustantivo', '/koʊt/', 'Put on your coat. It''s snowing.', 'Ponte el abrigo. Está nevando.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.suit', 'suit', 'traje (formal)', 'sustantivo', '/sut/', 'Carlos wears a suit to the office.', 'Carlos va de traje a la oficina.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.tie', 'tie', 'corbata', 'sustantivo', '/taɪ/', 'Do I need to wear a tie?', '¿Tengo que usar corbata?'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.shoes', 'shoes', 'zapatos', 'sustantivo', '/ʃuz/', 'Take off your shoes, please.', 'Quítate los zapatos, por favor.')
