    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.boots', 'boots', 'botas', 'sustantivo', '/buts/', 'My grandfather wears cowboy boots.', 'Mi abuelo usa botas vaqueras.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.socks', 'socks', 'calcetines', 'sustantivo', '/sɑks/', 'I can''t find my other sock!', '¡No encuentro mi otro calcetín!'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.cap', 'cap', 'gorra', 'sustantivo', '/kæp/', 'Ben always wears a baseball cap.', 'Ben siempre usa gorra de beisbol.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.hat', 'hat', 'sombrero / gorro', 'sustantivo', '/hæt/', 'Wear a hat. The sun is very strong.', 'Ponte un sombrero. El sol está muy fuerte.'),
    ((SELECT id FROM ingles_temas WHERE slug = 'ropa'), 'ropa.scarf', 'scarf', 'bufanda / pañoleta', 'sustantivo', '/skɑrf/', 'Grace has a warm wool scarf.', 'Grace tiene una bufanda de lana calientita.'),
