ON DUPLICATE KEY UPDATE ambito = VALUES(ambito), unidad_id = VALUES(unidad_id), leccion_id = VALUES(leccion_id), recurso = VALUES(recurso), tipo = VALUES(tipo), dificultad = VALUES(dificultad), habilidad = VALUES(habilidad);
