-- Evaluaciones de unidad y exámenes de bloque
ON DUPLICATE KEY UPDATE tipo = VALUES(tipo), unidad_id = VALUES(unidad_id), bloque_id = VALUES(bloque_id), titulo = VALUES(titulo), preguntas = VALUES(preguntas), aprobado = VALUES(aprobado);

